extern crate libc;
extern crate xcb;

use xcb::ffi::randr::*;
use xcb::ffi::*;

use libc::{c_void, free};
use std::ptr;

fn main() {
    unsafe {
        //Open connection to X server
        let conn = xcb_connect(ptr::null(), ptr::null_mut());

        //Get the first X screen
        let first_screen = xcb_setup_roots_iterator(xcb_get_setup(conn)).data;

        //Generate ID for the X window
        let window_dummy = xcb_generate_id(conn);

        //Create dummy X window
        xcb_create_window(
            conn,
            0,
            window_dummy,
            (*first_screen).root,
            0,
            0,
            1,
            1,
            0,
            0,
            0,
            0,
            ptr::null_mut(),
        );

        //Flush pending requests to the X server
        xcb_flush(conn);

        //Send a request for screen resources to the X server
        let screen_res_cookie = xcb_randr_get_screen_resources(conn, window_dummy);

        //Receive reply from X server
        let screen_res_reply =
            xcb_randr_get_screen_resources_reply(conn, screen_res_cookie, ptr::null_mut());

        if screen_res_reply.is_null() {
            panic!();
        }

        //Get a pointer to the first CRTC and number of CRTCs
        //It is crucial to notice that you are in fact getting
        //an array with firstCRTC being the first element of
        //this array and crtcs_length - length of this array
        let crtcs_num = xcb_randr_get_screen_resources_crtcs_length(screen_res_reply);
        let first_crtc = xcb_randr_get_screen_resources_crtcs(screen_res_reply);

        //Array of requests to the X server for CRTC info
        let mut crtc_res_cookies = Vec::with_capacity(crtcs_num as usize);
        crtc_res_cookies.set_len(crtcs_num as usize);
        for i in 0..crtcs_num {
            crtc_res_cookies[i as usize] =
                xcb_randr_get_crtc_info(conn, *first_crtc.offset(i as isize), 0);
        }

        for i in 0..crtcs_num {
            let reply =
                xcb_randr_get_crtc_info_reply(conn, crtc_res_cookies[i as usize], ptr::null_mut());
            if reply.is_null() {
                continue;
            }
            {
                let reply = &*reply;
                if i != 0 {
                    println!("");
                }
                println!("CRTC[{}] INFO:", i);
                println!(" x-off\t: {}", reply.x);
                println!(" y-off\t: {}", reply.y);
                println!(" width\t: {}", reply.width);
                println!(" height\t: {}", reply.height);
            }
            free(reply as *mut c_void);
        }

        xcb_disconnect(conn);
    }
}

use crate::delaunay::vertex::DVertex;

#[derive(Debug, Clone, Copy)]
pub struct DTriangle {
    pub index: usize,
    pub vertices: [DVertex; 3],
    pub neighbors: [usize; 3],
}

impl DTriangle {
    pub fn neighbor_by_order(&self, order: usize) -> usize {
        unsafe {
            *self.neighbors.get_unchecked(order)
        }
    }

    pub fn vertex_by_order(&self, order: usize) -> DVertex {
        unsafe {
            *self.vertices.get_unchecked(order)
        }
    }

    pub fn va(&self) -> DVertex {
        self.vertices[0]
    }

    pub fn vb(&self) -> DVertex {
        self.vertices[1]
    }

    pub fn vc(&self) -> DVertex {
        self.vertices[2]
    }

    pub fn na(&self) -> usize {
        self.neighbors[0]
    }

    pub fn nb(&self) -> usize {
        self.neighbors[1]
    }

    pub fn nc(&self) -> usize {
        self.neighbors[2]
    }

    pub fn new() -> Self {
        Self {
            index: usize::MAX,
            vertices: [DVertex::empty(); 3],
            neighbors: [usize::MAX; 3],
        }
    }

    pub fn abc(index: usize, a: DVertex, b: DVertex, c: DVertex) -> Self {
        Self {
            index,
            vertices: [a, b, c],
            neighbors: [usize::MAX; 3],
        }
    }

    pub fn abc_bc_ac_ab(index: usize, a: DVertex, b: DVertex, c: DVertex, bc: usize, ac: usize, ab: usize) -> Self {
        Self {
            index,
            vertices: [a, b, c],
            neighbors: [bc, ac, ab],
        }
    }

    pub fn neighbor(&self, vertex: usize) -> usize {
        #[cfg(debug_assertions)]
        {
            for i in 0..3 {
                if self.vertices[i].index == vertex {
                    return self.neighbors[i];
                }
            }

            panic!("Neighbor vertex is not present");
        }

        #[cfg(not(debug_assertions))]
        {
            for i in 0..2 {
                if self.vertices[i].index == vertex {
                    return self.neighbors[i];
                }
            }
            self.neighbors[2]
        }
    }

    pub fn opposite(&self, neighbor: usize) -> usize {
        #[cfg(debug_assertions)]
        {
            for i in 0..3 {
                if self.neighbors[i] == neighbor {
                    return i;
                }
            }

            panic!("Neighbor is not present");
        }

        #[cfg(not(debug_assertions))]
        {
            for i in 0..2 {
                if self.neighbors[i] == neighbor {
                    return i;
                }
            }

            2
        }
    }

    pub fn update_opposite(&mut self, old_neighbor: usize, new_neighbor: usize) {
        let index = self.opposite(old_neighbor);
        unsafe {
            *self.neighbors.get_unchecked_mut(index) = new_neighbor;
        }
    }
}

impl Default for DTriangle {
    fn default() -> Self {
        Self::new()
    }
}

/// Get the statement timeout duration, if any
pub fn timeout(&self) -> Option<Duration> {
	match self {
		Self::Create(v) => v.timeout.as_ref().map(|v| *v.0),
		Self::Delete(v) => v.timeout.as_ref().map(|v| *v.0),
		Self::Insert(v) => v.timeout.as_ref().map(|v| *v.0),
		Self::Relate(v) => v.timeout.as_ref().map(|v| *v.0),
		Self::Select(v) => v.timeout.as_ref().map(|v| *v.0),
		Self::Upsert(v) => v.timeout.as_ref().map(|v| *v.0),
		Self::Update(v) => v.timeout.as_ref().map(|v| *v.0),
		_ => None,
	}
}

